/**
 * Public contract for the on-demand, per-country deep-dive shown when a user
 * opens a country in the dashboard. Generated by a SEPARATE endpoint
 * (`/api/company-research/country-details`) so the main 15-country analysis
 * response stays small — this richer payload is fetched only when a country is
 * actually opened, then cached in the browser.
 *
 * Shared by server and browser code: pure types + a zod schema, no
 * `server-only`, no secrets, no natural-person data.
 */
import { z } from "zod";

/** Model confidence in this country deep-dive. */
export type CountryDetailsConfidence = "low" | "medium" | "high";

/** Fixed list sizes, mirrored by the schema below and re-validated server-side. */
export const COUNTRY_DETAILS_OPPORTUNITIES = 4;
export const COUNTRY_DETAILS_RISKS = 4;
export const COUNTRY_DETAILS_SEGMENTS = 3;
export const COUNTRY_DETAILS_BARRIERS = 3;
export const COUNTRY_DETAILS_FIRST_STEPS = 3;
/** Hard character cap for every free-text field, matching the analysis payload. */
export const COUNTRY_DETAILS_MAX_TEXT = 400;

export interface CountryDetails {
  /** Why the country earned its expansion score. */
  scoreRationale: string;
  /** Exactly 4 concrete opportunities. */
  opportunities: string[];
  /** Exactly 4 concrete risks. */
  risks: string[];
  /** Exactly 3 relevant customer segments in this market. */
  customerSegments: string[];
  /** Short competitive-landscape summary. */
  competition: string;
  /** Recommended market-entry model. */
  entryModel: string;
  /** Exactly 3 entry barriers. */
  barriers: string[];
  /** Exactly 3 concrete first steps. */
  firstSteps: string[];
  /** Overall confidence in this deep-dive. */
  confidenceLevel: CountryDetailsConfidence;
  /** Short justification for the confidence level. */
  confidenceRationale: string;
}

const boundedText = z.string().trim().min(1).max(COUNTRY_DETAILS_MAX_TEXT);

/**
 * Validates a country-details payload from the server before it is rendered or
 * restored from localStorage — a stored/returned value is never trusted blindly.
 */
export const countryDetailsSchema = z.strictObject({
  scoreRationale: boundedText,
  opportunities: z.array(boundedText).length(COUNTRY_DETAILS_OPPORTUNITIES),
  risks: z.array(boundedText).length(COUNTRY_DETAILS_RISKS),
  customerSegments: z.array(boundedText).length(COUNTRY_DETAILS_SEGMENTS),
  competition: boundedText,
  entryModel: boundedText,
  barriers: z.array(boundedText).length(COUNTRY_DETAILS_BARRIERS),
  firstSteps: z.array(boundedText).length(COUNTRY_DETAILS_FIRST_STEPS),
  confidenceLevel: z.enum(["low", "medium", "high"]),
  confidenceRationale: boundedText,
});

export type CountryDetailsParsed = z.infer<typeof countryDetailsSchema>;
